# Some portions generated by Codex. Bounded-memory JFR JSON event iterator, standard library only.
import json,re

def events(path):
    decoder=json.JSONDecoder()
    with open(path,encoding='utf-8') as stream:
        buf=''
        while True:
            chunk=stream.read(65536)
            if not chunk:raise ValueError('Missing JFR events array')
            buf+=chunk
            match=re.search(r'"events"\s*:\s*\[',buf)
            if match:
                buf=buf[match.end():]
                break
        while True:
            buf=buf.lstrip()
            if buf.startswith(','):buf=buf[1:].lstrip()
            if buf.startswith(']'):return
            try:
                value,end=decoder.raw_decode(buf)
            except json.JSONDecodeError:
                chunk=stream.read(65536)
                if not chunk:raise
                buf+=chunk
                continue
            if not isinstance(value,dict):raise ValueError('Expected event object')
            yield value
            buf=buf[end:]
